def has_unique_chars(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string.")

    if len(s) == 0:
        return True

    seen_chars = set()
    for char in s:
        if char in seen_chars:
            return False
        seen_chars.add(char)

    return True

