def find_longest_word_in_file(filepath):
    longest_word = ""
    try:
        with open(filepath, 'r') as file:
            for line in file:
                current_word = ""
                for char in line:
                    if char.isalnum():
                        current_word += char
                    else:
                        if len(current_word) > len(longest_word):
                            longest_word = current_word
                        current_word = ""
                if len(current_word) > len(longest_word):
                    longest_word = current_word
    except FileNotFoundError:
        return ""
    if not longest_word:
        return ""
    else:
        return longest_word

