    if n < 0:
        return False
    if n == 0:
        return True

    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2

        # Using a try-except block to handle potential overflow if mid*mid were
        # to exceed system limits for very large n, though unlikely for standard ints.
        try:
            if mid * mid == n:
                return True
            elif mid * mid < n:
                left = mid + 1
            else:
                right = mid - 1
        except OverflowError:
            # If overflow occurs, it means mid is too large, so the square is even larger
            right = mid - 1
            continue # Continue to next iteration

