def find_divisors(n):
    divisors = []
    if n <= 0:
        raise ValueError("Input must be a positive integer.")
    i = 1
    while i * i <= n:
        if n % i == 0:
            divisors.append(i)
            if i * i != n:
                divisors.append(n // i)
        i += 1
    divisors.sort()
    return divisors

