def justify_text_simple(words, max_width):
    if not words:
        return ""

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        if not current_line:
            current_line.append(word)
            current_length = len(word)
            continue

        if current_length + 1 + len(word) <= max_width:
            current_line.append(word)
            current_length += 1 + len(word)
        else:
            lines.append(" ".join(current_line))
            current_line = [word]
            current_length = len(word)

    if current_line:
        lines.append(" ".join(current_line))

    final_output = ""
    for i, line in enumerate(lines):
        final_output += line
        if i < len(lines) - 1:
            final_output += "\n"

    return final_output

