def calculate_sample_std_dev(numbers):
    if len(numbers) < 2:
        return 0.0

    total_sum = 0.0
    for num in numbers:
        total_sum += num

    mean = total_sum / len(numbers)

    sum_sq_diff = 0.0
    for num in numbers:
        diff = num - mean
        sum_sq_diff += diff ** 2

