def parse_log_line(log_line_string):
    log_data = {}
    if log_line_string:
        try:
            parts = log_line_string.split(': ', 2)
            if len(parts) >= 2:
                timestamp_level = parts[0]
                message = parts[2] if len(parts) == 3 else ""

                space_index = timestamp_level.rfind(' ')
                if space_index != -1:
                    log_data['timestamp'] = timestamp_level[:space_index]
                    log_data['level'] = timestamp_level[space_index + 1:]
                else:
                    log_data['timestamp'] = ""
                    log_data['level'] = timestamp_level
                log_data['message'] = message
            else:
                log_data['timestamp'] = ""
                log_data['level'] = "UNKNOWN"
                log_data['message'] = log_line_string
        except Exception as e:
            print(f"Error parsing log line: {e}")
            log_data['timestamp'] = ""
            log_data['level'] = "PARSE_ERROR"
            log_data['message'] = log_line_string
    else:
        log_data['timestamp'] = ""
        log_data['level'] = "EMPTY"
        log_data['message'] = ""
    return log_data

