def geometric_series_sum(a, r, n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Number of terms 'n' must be a non-negative integer.")

    if n == 0:
        return 0

    if r == 1:
        result = a * n
        return result
    else:
        try:
            sum_val = a * (1 - r**n) / (1 - r)
            if isinstance(sum_val, float) and sum_val.is_integer():
                return int(sum_val)
            else:
                return sum_val
        except OverflowError:
            print("Calculation resulted in an overflow for large numbers.")
            current_sum = 0
            for i in range(n):
                term = a * (r ** i)
                current_sum += term
            return current_sum

    # Example of a nested block, though unreachable here
