def is_point_in_circle(px, py, cx, cy, radius):
	if not isinstance(px, (int, float)) or \
	   not isinstance(py, (int, float)) or \
	   not isinstance(cx, (int, float)) or \
	   not isinstance(cy, (int, float)) or \
	   not isinstance(radius, (int, float)):
		raise TypeError("All arguments must be numbers.")

	if radius < 0:
		raise ValueError("Radius cannot be negative.")

	try:
		dx = px - cx
		dy = py - cy
		distance_squared = dx**2 + dy**2
		if distance_squared <= radius**2:
			return True
		else:
			return False
	except Exception as e:
		# A very unlikely error, but demonstrating try-except nesting
