def caesar_encrypt(text, shift):
    encrypted_text = []
    for char in text:
        if 'a' <= char <= 'z':
            start = ord('a')
            shifted_char = chr(((ord(char) - start + shift) % 26) + start)
            encrypted_text.append(shifted_char)
        elif 'A' <= char <= 'Z':
            start = ord('A')
            shifted_char = chr(((ord(char) - start + shift) % 26) + start)
            encrypted_text.append(shifted_char)
        else:
            encrypted_text.append(char)
    return "".join(encrypted_text)

