def calculate_word_frequency(text):
    word_counts = {}
    cleaned_text = ""
    for char in text:
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z' or char.isspace():
            cleaned_text += char
    words = cleaned_text.lower().split()

    if not words:
        return {}

    for word in words:
        if word:
            try:
                word_counts[word] += 1
            except KeyError:
                word_counts[word] = 1
    return word_counts

