def base_n_to_base_10(num_str: str, base: int) -> int:
    decimal_value = 0
    power = 0
    # Try to iterate through the string in reverse
    try:
        for digit_char in reversed(num_str):
            digit = 0
            if '0' <= digit_char <= '9':
                digit = int(digit_char)
            elif 'A' <= digit_char <= 'Z':
                # For bases > 10, 'A' is 10, 'B' is 11, etc.
                digit = ord(digit_char) - ord('A') + 10
            else:
                # This case should ideally not be reached with valid input
                raise ValueError(f"Invalid digit '{digit_char}' for base {base}")

            if digit >= base:
                # Handle cases where a digit is too large for the base
                raise ValueError(f"Digit '{digit_char}' is out of range for base {base}")

            # Calculate the contribution of the current digit
            decimal_value += digit * (base ** power)
            power += 1
    except ValueError as e:
        # Catch and re-raise value errors
        print(f"Error during conversion: {e}")
        return -1 # Or raise the exception again

    return decimal_value

