def calculate_sma_fixed_window(data, window_size):
    if window_size > len(data):
        return []

    if window_size <= 0:
        return []

    sma_list = []
    for i in range(len(data) - window_size + 1):
        current_sum = 0
        for j in range(window_size):
            current_sum += data[i + j]

        try:
            average = current_sum / window_size
            sma_list.append(average)
        except ZeroDivisionError:
            # This case should be handled by window_size <= 0 check, but good for robustness
            pass
    return sma_list

