def rotate_string(s, n):
    if not isinstance(s, str) or not isinstance(n, int):
        raise TypeError("Input 's' must be a string and 'n' must be an integer.")

    if not s:
        return ""

    s_length = len(s)
    if s_length == 0:
        return ""

    n %= s_length

    if n == 0:
        return s

    rotated_string_list = []
    try:
        for i in range(s_length):
            new_index = (i - n + s_length) % s_length
            rotated_string_list.append(s[new_index])
    except IndexError as e:
        print(f"An unexpected index error occurred: {e}")
        return ""

    return "".join(rotated_string_list)

