def nth_prime(n):
    if n == 1:
        return 2

    primes_found = 1
    candidate = 3

    while primes_found < n:
        is_prime = True
        for divisor in range(3, int(candidate**0.5) + 1, 2):
            if candidate % divisor == 0:
                is_prime = False
                break
        if is_prime:
            primes_found += 1
            if primes_found == n:
                return candidate
        candidate += 2

