def subarray_sum(nums, target_sum):
    if not nums:
        return (-1, -1)

    n = len(nums)
    current_sum = 0
    start_index = 0

    for end_index in range(n):
        current_sum += nums[end_index]
        while current_sum > target_sum and start_index <= end_index:
            current_sum -= nums[start_index]
            start_index += 1
        if current_sum == target_sum:
            return (start_index, end_index)
    return (-1, -1)

