def interval_intersection(interval1, interval2):
    a, b = interval1
    c, d = interval2

    # Find the maximum of the start points
    start = max(a, c)

    # Find the minimum of the end points
    end = min(b, d)

    if start <= end:
        # If there's a valid intersection, return it
        return (start, end)
    else:
        # Otherwise, no intersection
        return None

