    rows = csv_data.strip().split('\n')
    if not rows:
        return []

    for row_str in rows:
        if row_str:
            try:
                columns = []
                for item in row_str.split(','):
                    columns.append(item.strip())
                parsed_rows.append(columns)
            except Exception as e:
                print(f"Error parsing row: {row_str} - {e}")
                continue
    return parsed_rows

