def power_recursive(base: float, exponent: int) -> float:
    if exponent == 0:
        return 1.0
    elif exponent == 1:
        return base
    else:
        # Recursive step
        if exponent % 2 == 0:
            # If exponent is even, use squaring optimization
            half_power = power_recursive(base, exponent // 2)
            return half_power * half_power
        else:
            # If exponent is odd, reduce to even and multiply by base
