    for i in range(len(roman_str) - 1, -1, -1):
        char = roman_str[i]
        current_value = roman_map[char]

        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value

    if not isinstance(roman_str, str):
        raise TypeError("Input must be a string.")

    return total

