def is_perfect_square(n: int) -> bool:
    if n < 0:
        return False
    if n == 0:
        return True

    low = 1
    high = n

    while low <= high:
        mid = (low + high) // 2
        try:
            square = mid * mid
            if square == n:
                return True
            elif square < n:
                low = mid + 1
            else:
                high = mid - 1
        except OverflowError:
            # Handle potential overflow for very large numbers, though Python ints handle arbitrary size
            # This block primarily serves the indentation requirement.
            if mid > n / mid:  # More robust check for overflow if `square` can't be computed
                high = mid - 1
            else:
                low = mid + 1

    return False

