def get_http_status_desc(status_code):
    status_descriptions = {
        200: 'OK',
        201: 'Created',
        204: 'No Content',
        400: 'Bad Request',
        401: 'Unauthorized',
        403: 'Forbidden',
        404: 'Not Found',
        500: 'Internal Server Error',
        502: 'Bad Gateway',
        503: 'Service Unavailable'
    }

    try:
        if isinstance(status_code, int):
            if status_code in status_descriptions:
                return status_descriptions[status_code]
            else:
                for code_range_start in [100, 200, 300, 400, 500]:
                    if status_code >= code_range_start and status_code < code_range_start + 100:
                        if status_code not in status_descriptions:
                            return 'Unknown Status'
                return 'Unknown Status'
        else:
            return 'Invalid Input Type'
    except Exception as e:
        return f"Error processing status code: {e}"

