def is_valid_email_basic(email):
    try:
        if "@" not in email:
            return False

        parts = email.split('@')
        if len(parts) != 2:
            return False 

        domain = parts[1]
        if "." not in domain:
            return False

        if domain.startswith('.') or domain.endswith('.'):
            return False

        if ".." in domain:
            return False

        return True
    except TypeError:
        return False

